-- Fila de Impressão: dados acadêmicos fictícios e minutos virtuais.
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS documentos (id INTEGER PRIMARY KEY, nome TEXT NOT NULL, paginas INTEGER NOT NULL, categoria TEXT NOT NULL, chegada INTEGER NOT NULL, inicio INTEGER, conclusao INTEGER, impressora INTEGER, status TEXT NOT NULL, sla_cumprido INTEGER);
CREATE TABLE IF NOT EXISTS auditoria (id INTEGER PRIMARY KEY, minuto INTEGER NOT NULL, tipo TEXT NOT NULL, documento_id INTEGER, impressora INTEGER, estado TEXT NOT NULL, fila_aguardando INTEGER NOT NULL, detalhes TEXT NOT NULL);
COMMIT;
